script.code:
//Variables Externas
var TI = Ua.findNode("AGENT.OBJECTS.Simulation.Sistema_Llenado_Tanque.Caudal_Salida");
var TR = Ua.findNode("AGENT.OBJECTS.Simulation.Sistema_Llenado_Tanque.Caudal_Salida_Referencia");

//Variables Internas
var Vmax=TR.result.value;
var Vmin=Vmax-0.01;

//Ejecuto Logica
if(TR.result.value==0){
	TI.result.assign({value:0});
}
else{
	TI.result.assign({value: Vmin + (Math.random()*(Vmax-Vmin))});
}
